<script>
import infoDialog from '@/dialog/infoDialog.vue'
import * as XLSX from "xlsx"

    export default {
        components:{infoDialog},
        data(){
            return{
                infoState: false,
                oneState: true,
                twoState: true,
                thirdState: true,
                foruState: false,
                userList: [],
                infoList: [],
                excelList: [],
                authenticated: false,
                passwordInput: '',
                authFailed: false,
                excelListBackUp: [],
                snackbar: false,
                snackbarMessage: '',
                existingKeys: [],
            }
        },
        mounted(){
            this.userList =[
                {name: 'q224040'},
                {name: 'q224041'},
                {name: 'q220065'},
                {name: 'q223047'},
                {name: 'q223048'},
            ]
            if(!this.authenticated){
                this.$refs.pass.focus()
            }
        },
        
        methods:{
            onClickLeftMenuOne(){
                this.oneState  = !this.oneState
            },

            onClickLeftMenuTwo(){
                this.twoState = !this.twoState
            },

            onClickLeftMenuThird(){
                this.thirdState =!this.thirdState
            },

            onClickInfoOpen(){
                this.infoState = true
            },

            formatPhone(e) {
                let raw = e.target.value.replace(/[^0-9]/g, '')
                
                if (raw.length <= 3) {
                    this.infoObj.phone = raw
                } else if (raw.length <= 7) {
                    this.infoObj.phone = raw.replace(/(\d{3})(\d{1,4})/, '$1-$2')
                } else if (raw.length <= 11) {
                    this.infoObj.phone = raw.replace(/(\d{3})(\d{4})(\d{1,4})/, '$1-$2-$3')
                } else {
                    this.infoObj.phone = raw.slice(0, 11).replace(/(\d{3})(\d{4})(\d{4})/, '$1-$2-$3')
                }
            },

            onClickClose(){
                this.infoState = false
            },

            formatDate(yyMMdd) {
                if (!/^\d{6}$/.test(yyMMdd)) return '다시 입력하세요.';

                const yy = parseInt(yyMMdd.slice(0, 2), 10);
                const mm = yyMMdd.slice(2, 4);
                const dd = yyMMdd.slice(4, 6);

                // 기준 연도: 00~24는 2000년대, 나머지는 1900년대
                const year = yy < 26 ? 2000 + yy : 1900 + yy;

                return `${year}-${mm}-${dd}`;
            },
            

            onClickDone(obj){
                this.infoList.push({
                    key: obj.key,
                    customer: obj.customer,
                    name: obj.name,
                    birth: obj.birth,
                    phone: obj.phone,
                    buyDate: obj.buyDate,
                    telecom: obj.telecom,
                    emphysema: obj.emphysema,
                    date: obj.date
                });
                this.infoState = false
            },

            checkPassword() {
                const correctPassword = 'ict1004'
                if (this.passwordInput === correctPassword) {
                    this.authenticated = true
                } else {
                    this.authFailed = true
                    this.passwordInput = ''
                }
            },

            onClickLogOut(){
                this.infoList = []
            },

            goToHandy() {
                this.$router.push('/handy');
            },

           onExcelUpload(e) {
                const file = e.target.files[0]
                if (!file) {
                    this.snackbar = true
                    this.snackbarMessage = "엑셀 파일 오류"
                    return
                }

                const reader = new FileReader()
                reader.onload = (evt) => {
                    const data = evt.target.result
                    const workbook = XLSX.read(data, { type: "binary" })

                    const sheetName = workbook.SheetNames[0]
                    const sheet = workbook.Sheets[sheetName]

                    const rows = XLSX.utils.sheet_to_json(sheet, { header: 1 })

                    const result = rows.slice(1).map((row) => {
                        return {
                            KEY: this.generateUniqueKey(),
                            고객사: row[1] || "",
                            고객명: row[2] || "",
                            생년월일: row[3] || "",
                            연락처: row[4] || "",
                            통신사: row[5] || "",
                            구매단말: row[6] || "",
                            구매일시: row[7] || "",
                            가입일: row[8] || ""
                        }
                    })

                    this.excelList = result
                    this.excelListBackUp = [...result]
                }

                reader.readAsBinaryString(file)
                e.target.value = null;
                this.snackbar = true
                this.snackbarMessage = "엑셀 불러오기 완료"
            },

            showOnlyRow(idx) {
                this.excelList = [this.excelList[idx]]
            },

            resetExcelList() {
                if(this.excelListBackUp?.length == 0){
                    this.snackbar = true
                    this.snackbarMessage = "등록된 엑셀파일이 없습니다."
                    return
                }
                this.excelList = [...this.excelListBackUp];
            },
            
            onClickReset(){
                if(this.excelList?.length > 0 && this.excelListBackUp?.length > 0){
                    this.excelList = []
                    this.excelListBackUp = []
                    this.snackbar = true
                    this.snackbarMessage = "엑셀파일 초기화 완료"
                }else{
                    this.snackbar = true
                    this.snackbarMessage = "등록된 엑셀파일이 없습니다."
                }
            },

            generateUniqueKey() {
                let key
                do {
                    const randomNum = Math.floor(Math.random() * 1000000)
                    key = `E247_2${randomNum.toString().padStart(6, '0')}`
                } while (this.existingKeys.includes(key))
                    this.existingKeys.push(key)
                    return key
            },

        },
    }
</script>

